CREATE TABLE public.campaign_migration_backups (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), created_at timestamptz NOT NULL DEFAULT now(), reason text NOT NULL, snapshot jsonb NOT NULL);
GRANT ALL ON public.campaign_migration_backups TO service_role;
ALTER TABLE public.campaign_migration_backups ENABLE ROW LEVEL SECURITY;
INSERT INTO public.campaign_migration_backups(reason,snapshot) SELECT 'before weekly delivery migration', jsonb_build_object('rounds',(SELECT jsonb_agg(to_jsonb(t)) FROM public.letter_rounds t),'letters',(SELECT jsonb_agg(to_jsonb(t)) FROM public.campaign_letters t),'replies',(SELECT jsonb_agg(to_jsonb(t)) FROM public.letter_replies t),'receipts',(SELECT jsonb_agg(to_jsonb(t)) FROM public.letter_receipts t),'versions',(SELECT jsonb_agg(to_jsonb(t)) FROM public.letter_versions t),'records',(SELECT jsonb_agg(to_jsonb(t)) FROM public.campaign_records t),'players',(SELECT jsonb_agg(to_jsonb(t)) FROM public.campaign_players t),'houses',(SELECT jsonb_agg(to_jsonb(t)) FROM public.campaign_houses t),'memberships',(SELECT jsonb_agg(to_jsonb(t)) FROM public.house_memberships t),'bindings',(SELECT jsonb_agg(to_jsonb(t)) FROM public.drive_sync_bindings t),'files',(SELECT jsonb_agg(to_jsonb(t)) FROM public.drive_sync_files t),'outbox',(SELECT jsonb_agg(to_jsonb(t)) FROM public.sync_outbox t));
ALTER TABLE public.letter_rounds ADD COLUMN status text NOT NULL DEFAULT 'prepared', ADD COLUMN opened_by uuid, ADD COLUMN opened_at timestamptz, ADD COLUMN closed_by uuid, ADD COLUMN closed_at timestamptz;
UPDATE public.letter_rounds SET status=CASE WHEN closed THEN 'closed' ELSE 'open' END;
CREATE UNIQUE INDEX one_campaign_week_open ON public.letter_rounds ((status)) WHERE status='open';
ALTER TABLE public.campaign_letters ADD COLUMN conversation_id uuid, ADD COLUMN reply_to_id uuid, ADD COLUMN creation_week integer, ADD COLUMN delivery_week integer, ADD COLUMN publication_state text NOT NULL DEFAULT 'scheduled', ADD COLUMN delivered_at timestamptz, ADD COLUMN campaign_date text;
UPDATE public.campaign_letters SET conversation_id=coalesce(batch_key,id),creation_week=letter_number,delivery_week=letter_number,publication_state='delivered',delivered_at=created_at;
ALTER TABLE public.letter_replies ADD COLUMN conversation_id uuid, ADD COLUMN reply_to_id uuid, ADD COLUMN creation_week integer, ADD COLUMN delivery_week integer, ADD COLUMN publication_state text NOT NULL DEFAULT 'scheduled', ADD COLUMN delivered_at timestamptz, ADD COLUMN campaign_date text;
UPDATE public.letter_replies r SET conversation_id=l.conversation_id,reply_to_id=l.id,creation_week=l.letter_number,delivery_week=l.letter_number,publication_state='delivered',delivered_at=r.created_at FROM public.campaign_letters l WHERE l.id=r.letter_id;
CREATE OR REPLACE FUNCTION public.weekly_message_defaults() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE n integer; BEGIN n:=public.open_letter_round(); IF TG_TABLE_NAME='campaign_letters' THEN NEW.conversation_id:=coalesce(NEW.conversation_id,NEW.batch_key,NEW.id); NEW.creation_week:=coalesce(NEW.creation_week,n,NEW.letter_number); NEW.delivery_week:=coalesce(NEW.delivery_week,NEW.letter_number,n); NEW.letter_number:=NEW.delivery_week; END IF; IF NEW.publication_state NOT IN ('draft','scheduled','delivered') THEN RAISE EXCEPTION 'Situação inválida'; END IF; IF NEW.publication_state='scheduled' AND NEW.delivery_week=n THEN NEW.publication_state:='delivered'; NEW.delivered_at:=now(); END IF; RETURN NEW; END $$;
CREATE TRIGGER weekly_letter_defaults BEFORE INSERT ON public.campaign_letters FOR EACH ROW EXECUTE FUNCTION public.weekly_message_defaults();
CREATE TRIGGER weekly_reply_defaults BEFORE INSERT ON public.letter_replies FOR EACH ROW EXECUTE FUNCTION public.weekly_message_defaults();
CREATE OR REPLACE FUNCTION public.can_read_letter(l public.campaign_letters) RETURNS boolean LANGUAGE sql STABLE SET search_path=public AS $$ SELECT public.is_campaign_admin() OR (l.deleted_at IS NULL AND (l.sender_user_id=auth.uid() OR (l.publication_state='delivered' AND coalesce(public.letter_recipient(l),false)))) $$;
CREATE OR REPLACE FUNCTION public.can_read_reply(r public.letter_replies) RETURNS boolean LANGUAGE sql STABLE SET search_path=public AS $$ SELECT public.is_campaign_admin() OR r.author_user_id=auth.uid() OR (r.publication_state='delivered' AND r.recipient_user_id=auth.uid() AND EXISTS(SELECT 1 FROM public.campaign_letters l WHERE l.id=r.letter_id AND public.can_read_letter(l))) $$;
ALTER POLICY replies_read ON public.letter_replies USING (public.can_read_reply(letter_replies.*));
ALTER POLICY receipts_insert ON public.letter_receipts WITH CHECK (user_id=auth.uid() AND EXISTS(SELECT 1 FROM public.campaign_letters l WHERE l.id=letter_id AND l.publication_state='delivered' AND public.letter_recipient(l)));
CREATE OR REPLACE FUNCTION public.set_letter_round(p_number integer,p_closed boolean) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.is_campaign_admin() THEN RAISE EXCEPTION 'Somente o Narrador abre ou encerra semanas'; END IF; IF p_number IS NULL OR p_number<1 THEN RAISE EXCEPTION 'Semana inválida'; END IF; PERFORM pg_advisory_xact_lock(184522); IF NOT p_closed AND EXISTS(SELECT 1 FROM public.letter_rounds WHERE number=p_number AND status='closed') THEN RAISE EXCEPTION 'Semana histórica encerrada não pode ser reaberta'; END IF; IF NOT p_closed THEN UPDATE public.letter_rounds SET closed=true,status='closed',closed_by=auth.uid(),closed_at=now(),updated_at=now() WHERE status='open' AND number<>p_number; END IF; INSERT INTO public.letter_rounds(number,closed,status,opened_by,opened_at,closed_by,closed_at) VALUES(p_number,p_closed,CASE WHEN p_closed THEN 'closed' ELSE 'open' END,CASE WHEN NOT p_closed THEN auth.uid() END,CASE WHEN NOT p_closed THEN now() END,CASE WHEN p_closed THEN auth.uid() END,CASE WHEN p_closed THEN now() END) ON CONFLICT(number) DO UPDATE SET closed=excluded.closed,status=excluded.status,opened_by=coalesce(letter_rounds.opened_by,excluded.opened_by),opened_at=coalesce(letter_rounds.opened_at,excluded.opened_at),closed_by=excluded.closed_by,closed_at=excluded.closed_at,updated_at=now(); IF NOT p_closed THEN UPDATE public.campaign_letters SET publication_state='delivered',delivered_at=now() WHERE delivery_week=p_number AND publication_state='scheduled'; UPDATE public.letter_replies SET publication_state='delivered',delivered_at=now() WHERE delivery_week=p_number AND publication_state='scheduled'; INSERT INTO public.sync_outbox(entity_type,entity_id,version,payload) SELECT 'letter',id,version,to_jsonb(l) FROM public.campaign_letters l WHERE delivery_week=p_number AND publication_state='delivered' ON CONFLICT DO NOTHING; INSERT INTO public.sync_outbox(entity_type,entity_id,version,payload) SELECT 'reply',id,1,to_jsonb(r) FROM public.letter_replies r WHERE delivery_week=p_number AND publication_state='delivered' ON CONFLICT DO NOTHING; UPDATE public.sync_outbox SET state='pending',next_attempt_at=now() WHERE entity_id IN (SELECT id FROM public.campaign_letters WHERE delivery_week=p_number UNION SELECT id FROM public.letter_replies WHERE delivery_week=p_number); END IF; END $$;
CREATE OR REPLACE FUNCTION public.prepare_letter_week(p_number integer) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.is_campaign_admin() THEN RAISE EXCEPTION 'Somente o Narrador prepara semanas'; END IF; IF p_number<1 THEN RAISE EXCEPTION 'Semana inválida'; END IF; INSERT INTO public.letter_rounds(number,closed,status) VALUES(p_number,true,'prepared') ON CONFLICT(number) DO NOTHING; END $$;
CREATE OR REPLACE FUNCTION public.reply_weekly_message(p_letter uuid,p_reply uuid,p_content text,p_key uuid,p_draft boolean DEFAULT false) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE l public.campaign_letters; prior public.letter_replies; rid uuid; n integer; delivery integer; recipient uuid; pname text; gm boolean:=public.is_campaign_admin(); BEGIN SELECT * INTO l FROM public.campaign_letters WHERE id=p_letter FOR UPDATE; IF NOT FOUND OR l.deleted_at IS NOT NULL OR NOT public.can_read_letter(l) THEN RAISE EXCEPTION 'Missiva indisponível'; END IF; n:=public.open_letter_round(); IF NOT gm AND public.my_player_id() IS NULL THEN RAISE EXCEPTION 'Jogador não autorizado'; END IF; IF NOT gm AND n IS NULL AND NOT p_draft THEN RAISE EXCEPTION 'Missivas fechadas, aguarde o narrador abrir a próxima semana'; END IF; IF p_reply IS NOT NULL THEN SELECT * INTO prior FROM public.letter_replies WHERE id=p_reply AND letter_id=p_letter; IF NOT FOUND OR NOT public.can_read_reply(prior) THEN RAISE EXCEPTION 'Resposta indisponível'; END IF; recipient:=prior.author_user_id; ELSE recipient:=l.sender_user_id; END IF; IF recipient=auth.uid() THEN RAISE EXCEPTION 'Selecione a mensagem recebida à qual deseja responder'; END IF; IF btrim(p_content)='' THEN RAISE EXCEPTION 'Escreva a resposta'; END IF; SELECT id INTO rid FROM public.letter_replies WHERE author_user_id=auth.uid() AND idempotency_key=p_key; IF FOUND THEN RETURN rid; END IF; n:=coalesce(n,(SELECT coalesce(max(number),0)+1 FROM public.letter_rounds)); delivery:=CASE WHEN gm OR NOT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=recipient AND role='admin') THEN n+1 ELSE n END; IF gm THEN pname:='Mestre'; ELSE SELECT name INTO pname FROM public.campaign_players WHERE id=public.my_player_id(); END IF; INSERT INTO public.letter_replies(letter_id,author_user_id,author_player_id,author_name,house_id,recipient_user_id,content,idempotency_key,conversation_id,reply_to_id,creation_week,delivery_week,publication_state) VALUES(l.id,auth.uid(),public.my_player_id(),coalesce(pname,'Jogador'),l.recipient_house_id,recipient,p_content,p_key,l.conversation_id,coalesce(p_reply,l.id),n,delivery,CASE WHEN p_draft THEN 'draft' ELSE 'scheduled' END) RETURNING id INTO rid; IF NOT gm AND NOT p_draft THEN INSERT INTO public.letter_receipts(letter_id,user_id) VALUES(l.id,auth.uid()) ON CONFLICT DO NOTHING; END IF; RETURN rid; END $$;
CREATE OR REPLACE FUNCTION public.reply_campaign_letter(p_letter uuid,p_content text,p_key uuid) RETURNS uuid LANGUAGE sql SECURITY DEFINER SET search_path=public AS $$ SELECT public.reply_weekly_message(p_letter,NULL,p_content,p_key,false) $$;
CREATE OR REPLACE FUNCTION public.save_letter_draft(p_id uuid,p_house text,p_subject text,p_content text,p_week integer) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE pid uuid:=public.my_player_id(); pname text; BEGIN IF NOT public.is_campaign_admin() AND (pid IS NULL OR NOT EXISTS(SELECT 1 FROM public.house_memberships WHERE player_id=pid)) THEN RAISE EXCEPTION 'Jogador não autorizado'; END IF; IF public.is_campaign_admin() THEN pname:='Mestre'; ELSE SELECT name INTO pname FROM public.campaign_players WHERE id=pid; END IF; INSERT INTO public.campaign_letters(id,sender_user_id,sender_player_id,sender_name,recipient_house_id,subject,content,letter_kind,letter_number,publication_state) VALUES(p_id,auth.uid(),pid,pname,p_house,p_subject,p_content,'reservada',p_week,'draft') ON CONFLICT(id) DO UPDATE SET subject=excluded.subject,content=excluded.content,recipient_house_id=excluded.recipient_house_id,delivery_week=excluded.letter_number,letter_number=excluded.letter_number WHERE campaign_letters.sender_user_id=auth.uid() AND campaign_letters.publication_state='draft'; IF NOT FOUND THEN RAISE EXCEPTION 'Rascunho indisponível'; END IF; RETURN p_id; END $$;
CREATE OR REPLACE FUNCTION public.schedule_letter_draft(p_id uuid,p_week integer) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE n integer:=public.open_letter_round(); BEGIN IF NOT public.is_campaign_admin() AND n IS NULL THEN RAISE EXCEPTION 'Missivas fechadas, aguarde o narrador abrir a próxima semana'; END IF; UPDATE public.campaign_letters SET delivery_week=CASE WHEN public.is_campaign_admin() THEN p_week ELSE n END,letter_number=CASE WHEN public.is_campaign_admin() THEN p_week ELSE n END,creation_week=n,publication_state=CASE WHEN coalesce(p_week,n)=n THEN 'delivered' ELSE 'scheduled' END,delivered_at=CASE WHEN coalesce(p_week,n)=n THEN now() END WHERE id=p_id AND sender_user_id=auth.uid() AND publication_state='draft' AND btrim(subject)<>'' AND btrim(content)<>''; IF NOT FOUND THEN RAISE EXCEPTION 'Preencha o rascunho antes de enviar'; END IF; END $$;
REVOKE ALL ON FUNCTION public.reply_weekly_message(uuid,uuid,text,uuid,boolean),public.prepare_letter_week(integer),public.save_letter_draft(uuid,text,text,text,integer),public.schedule_letter_draft(uuid,integer) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.reply_weekly_message(uuid,uuid,text,uuid,boolean),public.prepare_letter_week(integer),public.save_letter_draft(uuid,text,text,text,integer),public.schedule_letter_draft(uuid,integer) TO authenticated;
ALTER POLICY campaign_images_read ON storage.objects USING (bucket_id='campaign-images' AND (public.is_campaign_admin() OR (storage.foldername(name))[1]=auth.uid()::text OR EXISTS(SELECT 1 FROM public.campaign_letters l WHERE public.can_read_letter(l) AND position('[cormyr-image:'||objects.name||'|' in l.content)>0) OR EXISTS(SELECT 1 FROM public.letter_replies r WHERE public.can_read_reply(r) AND position('[cormyr-image:'||objects.name||'|' in r.content)>0) OR EXISTS(SELECT 1 FROM public.campaign_records r WHERE public.can_read_record(r) AND position('[cormyr-image:'||objects.name||'|' in r.content)>0)));
COMMENT ON COLUMN public.campaign_letters.letter_number IS 'Compatibility label: campaign delivery week, not individual letter sequence';